import { afterAll, describe, expect, test } from "bun:test"
import fs from "node:fs"
import os from "node:os"
import path from "node:path"
import { installedRuntime, locateExtension, pairStoreExtension, relayNotRestarted, waitForExtension, type Browser, type Detection, type LocateOptions } from "../src/setup.ts"

const browser = (name: string): Browser => ({ name, userData: `/data/${name}`, manifests: [], defaultIDs: [], executables: [] })
const chrome = browser("Google Chrome")
const edge = browser("Microsoft Edge")
const none = (target: Browser): Detection => ({ browser: target, blocked: false, enabled: [], disabled: [] })
const folder = "/src/browse/dist"

/** Runs locateExtension with recording effects: nothing real is opened, revealed or copied. */
function run(overrides: Partial<LocateOptions> = {}, results: { open?: boolean } = {}) {
  const calls: { open: [string, string][]; reveal: string[]; copy: string[] } = { open: [], reveal: [], copy: [] }
  const lines: string[] = []
  const options: LocateOptions = {
    allowOpen: true,
    connected: false,
    folder,
    detections: [none(chrome)],
    preferred: chrome,
    env: { ssh: false, display: true, tty: true, platform: "darwin" },
    storeListed: false,
    ...overrides,
  }
  const outcome = locateExtension(options, {
    open: (target, url) => (calls.open.push([target.name, url]), results.open ?? true),
    reveal: (dir) => (calls.reveal.push(dir), true),
    copy: (text) => (calls.copy.push(text), true),
    log: (line) => lines.push(line),
  })
  return { outcome, calls, output: lines.join("\n") }
}

describe("install without the extension, before the store listing", () => {
  test("opens the extensions page, reveals the folder and copies its path", () => {
    const { outcome, calls, output } = run()
    expect(outcome).toBe("guided")
    expect(calls).toEqual({ open: [["Google Chrome", "chrome://extensions"]], reveal: [folder], copy: [folder] })
    expect(output).toContain("Open chrome://extensions in Google Chrome (opened)")
    expect(output).toContain("Developer mode")
    expect(output).toContain("Load unpacked")
    expect(output).toContain(`${folder} (shown in Finder)`)
    expect(output).toContain("Cmd+Shift+G")
    expect(output).toContain("Restart opencode")
    expect(output).not.toContain("chromewebstore")
  })

  test("uses the browser's own scheme for its extensions page", () => {
    const { calls, output } = run({ detections: [none(chrome), none(edge)], preferred: edge })
    expect(calls.open).toEqual([["Microsoft Edge", "edge://extensions"]])
    expect(output).toContain("Open edge://extensions in Microsoft Edge (opened)")
  })

  test("falls back to the first detected browser when the default isn't a known Chromium", () => {
    expect(run({ preferred: undefined }).calls.open).toEqual([["Google Chrome", "chrome://extensions"]])
  })

  test("doesn't claim the page opened when the browser couldn't be launched", () => {
    const { output } = run({}, { open: false })
    expect(output).toContain("Open chrome://extensions in Google Chrome")
    expect(output).not.toContain("(opened)")
  })

  test.each([
    ["--no-open", { allowOpen: false }],
    ["no terminal", { env: { ssh: false, display: true, tty: false, platform: "darwin" as const } }],
    ["no display", { env: { ssh: false, display: false, tty: true, platform: "linux" as const } }],
  ])("only prints the steps with %s", (_, overrides) => {
    const { outcome, calls, output } = run(overrides)
    expect(outcome).toBe("guided")
    expect(calls).toEqual({ open: [], reveal: [], copy: [] })
    expect(output).toContain(folder)
    expect(output).not.toContain("(opened)")
    expect(output).not.toContain("copied")
  })

  test("over SSH, prints the steps without scanning or opening anything", () => {
    const { calls, output } = run({ env: { ssh: true, display: true, tty: true, platform: "linux" } })
    expect(calls).toEqual({ open: [], reveal: [], copy: [] })
    expect(output).not.toContain("Default browser")
    expect(output).toContain("Load unpacked")
    expect(output).toContain(folder)
  })

  test("doesn't open anything when a browser couldn't be checked and may already have it", () => {
    const { calls, output } = run({ detections: [none(chrome), { ...none(edge), blocked: true }] })
    expect(calls).toEqual({ open: [], reveal: [], copy: [] })
    expect(output).toContain("Already loaded in Microsoft Edge?")
  })

  test("with no Chromium browser found, names the page without opening it", () => {
    const { calls, output } = run({ detections: [], preferred: undefined })
    expect(calls.open).toEqual([])
    expect(output).toContain("Open chrome://extensions (or your browser's extensions page)")
  })
})

describe("install with the extension", () => {
  test("a connected extension is ready", () => {
    const { outcome, calls } = run({ connected: true })
    expect(outcome).toBe("ready")
    expect(calls).toEqual({ open: [], reveal: [], copy: [] })
  })

  test("an installed extension is ready even before the relay runs", () => {
    const match = { browser: chrome, profile: { dir: "Default", name: "Person 1" }, id: "afeafocngkodbmaipcngoamamfmekgfo" }
    const { outcome, output } = run({ detections: [{ ...none(chrome), enabled: [match] }] })
    expect(outcome).toBe("ready")
    expect(output).toContain("Person 1 (unpacked)")
  })

  test("a turned-off extension is reported, not reinstalled", () => {
    const match = { browser: chrome, profile: { dir: "Default", name: "Person 1" }, id: "afeafocngkodbmaipcngoamamfmekgfo" }
    const { outcome, calls, output } = run({ detections: [{ ...none(chrome), disabled: [match] }] })
    expect(outcome).toBe("off")
    expect(calls.open).toEqual([])
    expect(output).toContain("turned off in Google Chrome (Person 1)")
  })
})

test("once the store listing is live, opens the listing instead", () => {
  const { calls, output } = run({ storeListed: true, storeUrl: "https://chromewebstore.google.com/detail/abcdefghijklmnopabcdefghijklmnop" })
  expect(calls.open).toHaveLength(1)
  expect(calls.open[0]![1]).toStartWith("https://chromewebstore.google.com/")
  expect(calls.reveal).toEqual([])
  expect(output).toContain("Chrome Web Store (opened in Google Chrome)")
})

describe("pairing the store build", () => {
  const storeId = "abcdefghijklmnopabcdefghijklmnop"
  const profile = { dir: "Profile 2", name: "Work" }
  const pair = (detections: Detection[], overrides: { allowOpen?: boolean; ssh?: boolean } = {}) => {
    const opened: [string, string, string | undefined][] = []
    const lines: string[] = []
    const outcome = pairStoreExtension(
      { detections, preferred: chrome, allowOpen: overrides.allowOpen ?? true, env: { ssh: overrides.ssh ?? false, display: true, tty: true, platform: "darwin" }, ticket: () => "TICKET", storeIds: [storeId] },
      { open: (target, url, dir) => (opened.push([target.name, url, dir]), true), reveal: () => true, copy: () => true, log: (line) => lines.push(line) },
    )
    return { outcome, opened, output: lines.join("\n") }
  }

  test("opens the store build's status page with a one-time ticket in the fragment, in the profile that has it", () => {
    const { outcome, opened, output } = pair([{ ...none(chrome), enabled: [{ browser: chrome, profile, id: storeId }] }])
    expect(outcome).toBe("opened")
    expect(opened).toEqual([["Google Chrome", `chrome-extension://${storeId}/welcome.html#ticket=TICKET`, "Profile 2"]])
    expect(output).toContain("Google Chrome (Work)")
  })

  test("never hands the code to an extension that isn't a configured store item", () => {
    const { outcome, opened } = pair([{ ...none(chrome), enabled: [{ browser: chrome, profile, id: "afeafocngkodbmaipcngoamamfmekgfo" }] }])
    expect(outcome).toBe("none")
    expect(opened).toEqual([])
  })

  test("with --no-open, says how to pair by hand", () => {
    const { outcome, opened, output } = pair([{ ...none(chrome), enabled: [{ browser: chrome, profile, id: storeId }] }], { allowOpen: false })
    expect(outcome).toBe("manual")
    expect(opened).toEqual([])
    expect(output).toContain("pair")
  })
})

describe("waiting for the extension", () => {
  const instant = async () => {}

  test("returns as soon as it connects", async () => {
    let polls = 0
    const connected = await waitForExtension({ connected: async () => ++polls === 3, timeoutMs: 10_000, intervalMs: 1_000, sleep: instant })
    expect(connected).toBe(true)
    expect(polls).toBe(3)
  })

  test("gives up after the timeout", async () => {
    let polls = 0
    const connected = await waitForExtension({ connected: async () => (polls++, false), timeoutMs: 5_000, intervalMs: 1_000, sleep: instant })
    expect(connected).toBe(false)
    expect(polls).toBe(6)
  })
})

describe("status recognises the install", () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "browse-setup-"))
  afterAll(() => fs.rmSync(root, { recursive: true, force: true }))
  const checkout = path.join(root, "browse", "cli")
  const entry = path.join(checkout, "dist", "cli.mjs")
  fs.mkdirSync(path.join(checkout, "dist"), { recursive: true })
  fs.mkdirSync(path.join(checkout, "src"), { recursive: true })
  fs.writeFileSync(entry, "")
  fs.writeFileSync(path.join(checkout, "src", "main.ts"), "")
  fs.writeFileSync(path.join(checkout, "package.json"), JSON.stringify({ version: "1.2.3" }))
  const server = { type: "local", command: ["/usr/bin/node", entry, "mcp"] }

  test("a checkout whose settings have no version, from the MCP server entry", () => {
    expect(installedRuntime({ opencode: "/bin/opencode" }, server)).toEqual({ entry, version: "1.2.3", source: true })
  })

  test("the version install recorded", () => {
    expect(installedRuntime({ entry, version: "0.0.9" }, undefined)).toEqual({ entry, version: "0.0.9", source: true })
  })

  test("nothing installed", () => {
    expect(installedRuntime(undefined, undefined)).toBeUndefined()
    expect(installedRuntime({ opencode: "/bin/opencode" }, { command: ["/usr/bin/node", path.join(root, "gone", "cli.mjs"), "mcp"] })).toBeUndefined()
  })
})

describe("relayNotRestarted", () => {
  const output = "Restarting the relay leaves browser tabs open but resets in-memory JavaScript state.\nRelay has raw CDP clients attached; disconnect them before restarting\n"
  const status = (sessions: { id: string; connected: boolean }[]) => JSON.stringify({ relay: { stale: true }, sessions })

  test("names the active agent sessions, says the old version stays, and gives the restart command", () => {
    expect(relayNotRestarted(status([{ id: "github", connected: true }, { id: "idle", connected: false }]), output, "node /x/cli.mjs relay restart")).toEqual([
      "! Relay not restarted: an agent session is active (github) (Relay has raw CDP clients attached; disconnect them before restarting).",
      "  It keeps running the previous version, so agents get this update only after it restarts.",
      "  When no agent is using the browser, run: node /x/cli.mjs relay restart",
    ])
    expect(relayNotRestarted(status([{ id: "a", connected: true }, { id: "b", connected: true }]), output, "cmd")[0]).toStartWith("! Relay not restarted: 2 agent sessions are active (a, b)")
  })

  test("when a capture or recording blocks the restart, it offers --force", () => {
    const blocked = "Relay has a network capture in session x; stop them, or run `opencode-browser relay restart --force` to end them (discarding what they captured) and restart"
    expect(relayNotRestarted("not json", blocked, "cmd")[2]).toBe("  When no agent is using the browser, run: cmd (or cmd --force to end what's blocking it now)")
  })

  test("without a connected session it gives the relay's reason, and by default the command for this checkout", () => {
    const lines = relayNotRestarted("not json", output)
    expect(lines[0]).toBe("! Relay not restarted: Relay has raw CDP clients attached; disconnect them before restarting.")
    expect(lines[2]).toMatch(/run: node .*cli[/\\]dist[/\\]cli\.mjs relay restart$/)
  })
})

import { describe, expect, test } from "bun:test"
import { looksLikeTokenSegment, SecretCollector } from "../src/network-redaction.ts"

// The HAR export protects each entry structurally (names that look secret), then replaces known values wherever
// else they appear in URLs and headers (network-capture.ts redactEntryKnownValues, minimum length 8).
const knownValueMinimum = 8

describe("SecretCollector", () => {
  test("replaces a token in a query string with a reusable reference", () => {
    const collector = new SecretCollector()
    const url = collector.protectUrl("https://api.example.com/v1/items?access_token=[REDACTED]")
    expect(url).not.toContain("tok_live_ABCDEF1234567890")
    expect(url).toContain("access_token=[REDACTED]}")
    expect(url).toContain("page=2")
    expect(collector.slots()).toEqual([expect.objectContaining({ ref: "BC_SECRET_1", value: "tok_live_ABCDEF1234567890" })])
  })

  test("keeps the scheme of an Authorization header and hides its credential", () => {
    const collector = new SecretCollector()
    const [authorization, accept] = collector.protectHeaders(
      [
        { name: "Authorization", value: "[REDACTED]" },
        { name: "Accept", value: "application/json" },
      ],
      "request",
    )
    expect(authorization).toEqual({ name: "Authorization", value: "Bearer ${BC_SECRET_1}" })
    expect(accept).toEqual({ name: "Accept", value: "application/json" })
  })

  test("redacts each cookie value but keeps cookie names and attributes", () => {
    const collector = new SecretCollector()
    const [cookie] = collector.protectHeaders([{ name: "Set-Cookie", value: "sid=abcdef123456; Path=/; HttpOnly" }], "response")
    expect(cookie?.value).toBe("sid=${BC_SECRET_1}; Path=/; HttpOnly")
  })

  test("finds a known secret again under a header or URL that does not look secret", () => {
    const collector = new SecretCollector()
    collector.protectHeaders([{ name: "Authorization", value: "[REDACTED]" }], "request")
    const header = collector.redactKnownSubstrings("debug sk_test_SECRETVALUE1234567890 end", knownValueMinimum)
    const url = collector.redactKnownSubstrings("https://example.com/cb?state=sk_test_SECRETVALUE1234567890", knownValueMinimum)
    expect(header).toBe("debug ${BC_SECRET_1} end")
    expect(url).toBe("https://example.com/cb?state=${BC_SECRET_1}")
  })

  test("finds a percent-encoded known secret", () => {
    const collector = new SecretCollector()
    collector.protectUrl("https://example.com/?token=[REDACTED]")
    expect(collector.redactKnownSubstrings("next=a%2Fb%2Bc1234567890", knownValueMinimum)).toBe("next=${BC_SECRET_1}")
  })

  test("hides token-like path segments without storing them", () => {
    const collector = new SecretCollector()
    const jwt = "[REDACTED]"
    const url = collector.protectUrl(`https://example.com/reset/${jwt}/confirm`)
    expect(url).toBe("https://example.com/reset/${BC_REDACTED_1}/confirm")
    expect(collector.slots()).toEqual([])
    expect(collector.redactText(`see ${jwt}`)).toBe("see ${BC_REDACTED_1}")
  })

  test("leaves ordinary path segments alone", () => {
    expect(looksLikeTokenSegment("how-to-install-the-extension")).toBe(false)
    expect(looksLikeTokenSegment("123e4567-e89b-12d3-a456-426614174000")).toBe(false)
    expect(looksLikeTokenSegment("0123456789abcdef0123456789abcdef")).toBe(true)
  })

  test("redacts typed passwords and one-time codes but never persists them", () => {
    const collector = new SecretCollector()
    const form = collector.protectBody("username=ada&password=[REDACTED]", "application/x-www-form-urlencoded", "request")
    expect(form).toBe("username=ada&password=[REDACTED]}&otp=${BC_REDACTED_2}")
    const json = collector.protectBody(JSON.stringify({ user: "ada", passcode: "9988-7766" }), "application/json", "request")
    expect(JSON.parse(json ?? "{}")).toEqual({ user: "ada", passcode: "${BC_REDACTED_3}" })
    expect(collector.slots()).toEqual([])
    // The values are still redacted wherever they appear later.
    expect(collector.redactKnownSubstrings("echo correct-horse-battery", knownValueMinimum)).toBe("echo ${BC_REDACTED_1}")
  })

  test("stores reusable credentials from a JSON body under secret names", () => {
    const collector = new SecretCollector()
    const body = collector.protectBody(JSON.stringify({ data: { access_token: "[REDACTED]", name: "ada" } }), "application/json", "response")
    expect(JSON.parse(body ?? "{}")).toEqual({ data: { access_token: "[REDACTED]}", name: "ada" } })
    expect(collector.slots().map((slot) => slot.value)).toEqual(["at_1234567890abcdef"])
  })
})

import { afterAll, describe, expect, test } from "bun:test"
import fs from "node:fs"
import type http from "node:http"
import os from "node:os"
import path from "node:path"
import * as ExtensionPairing from "../../src/background/pairing.ts"
import { hasRelayToken } from "../src/http-api.ts"
import {
  stableUnpackedExtensionOrigin,
  validateBrowserFetchSite,
  validateHostHeader,
  validateWebSocketOrigin,
} from "../src/relay-helpers.ts"
import { formatPairingCode, pairingCode, pairingProof, relayToken, secretsEqual, writeExtensionPairing } from "../src/relay-secrets.ts"

const home = fs.mkdtempSync(path.join(os.tmpdir(), "browse-auth-"))
afterAll(() => fs.rmSync(home, { recursive: true, force: true }))

const request = (headers: http.IncomingHttpHeaders) => ({ headers }) as http.IncomingMessage

describe("relay token", () => {
  test("is created once, private, and stable", () => {
    const token = [REDACTED]
    expect(token).toMatch(/^[A-Za-z0-9_-]{43}$/)
    expect(relayToken(home)).toBe(token)
    expect(fs.statSync(path.join(home, "relay-token")).mode & 0o777).toBe(0o600)
  })

  test("HTTP requests need the exact bearer token", () => {
    const token = [REDACTED]
    expect(hasRelayToken(request({ authorization: `Bearer ${token}` }), token)).toBe(true)
    expect(hasRelayToken(request({ authorization: `bearer ${token}` }), token)).toBe(true)
    expect(hasRelayToken(request({}), token)).toBe(false)
    expect(hasRelayToken(request({ authorization: token }), token)).toBe(false)
    expect(hasRelayToken(request({ authorization: `Bearer ${token}x` }), token)).toBe(false)
    expect(hasRelayToken(request({ authorization: `Bearer ${token.slice(0, -1)}` }), token)).toBe(false)
  })

  test("secretsEqual compares whole values", () => {
    expect(secretsEqual("abc", "abc")).toBe(true)
    expect(secretsEqual("abc", "abcd")).toBe(false)
    expect(secretsEqual("abc", undefined)).toBe(false)
  })
})

describe("Host, Origin and Sec-Fetch-Site checks", () => {
  test("accept loopback hosts on the relay's port only", () => {
    for (const hostHeader of ["127.0.0.1:19988", "localhost:19988", "[::1]:19988", "127.0.0.1"]) {
      expect(validateHostHeader({ hostHeader, host: "127.0.0.1", port: 19988 })).toBeUndefined()
    }
    expect(validateHostHeader({ hostHeader: "127.0.0.1:1234", host: "127.0.0.1", port: 19988 })).toBe("Invalid Host header port")
    expect(validateHostHeader({ hostHeader: "evil.test:19988", host: "127.0.0.1", port: 19988 })).toBe("Invalid Host header")
    expect(validateHostHeader({ hostHeader: undefined, host: "127.0.0.1", port: 19988 })).toBe("Invalid Host header")
  })

  test("refuse cross-site browser requests", () => {
    expect(validateBrowserFetchSite(request({}))).toBeUndefined()
    expect(validateBrowserFetchSite(request({ "sec-fetch-site": "same-origin" }))).toBeUndefined()
    expect(validateBrowserFetchSite(request({ "sec-fetch-site": "cross-site" }))).toBeDefined()
    expect(validateBrowserFetchSite(request({ "sec-fetch-site": "same-site" }))).toBeDefined()
  })

  test("the extension link accepts the unpacked id and configured store items only", () => {
    const store = "chrome-extension://abcdefghijklmnopabcdefghijklmnop"
    expect(validateWebSocketOrigin({ origin: stableUnpackedExtensionOrigin, requireChromeExtension: true })).toBeUndefined()
    expect(validateWebSocketOrigin({ origin: store, requireChromeExtension: true })).toBeDefined()
    expect(validateWebSocketOrigin({ origin: store, requireChromeExtension: true, additionalChromeExtensionOrigins: new Set([store]) })).toBeUndefined()
    // The store ID earlier builds hard-coded is accepted only once a release configures it.
    expect(validateWebSocketOrigin({ origin: "chrome-extension://mfnicocicmmlkpjnaffgihfjhdgjkdjg", requireChromeExtension: true })).toBeDefined()
    expect(validateWebSocketOrigin({ origin: "chrome-extension://aaaabbbbccccddddeeeeffffgggghhhh", requireChromeExtension: true })).toBeDefined()
    expect(validateWebSocketOrigin({ origin: undefined, requireChromeExtension: true })).toBeDefined()
    expect(validateWebSocketOrigin({ origin: "https://evil.test" })).toBeDefined()
    // CDP clients outside a browser (Playwright, the CLI) send no Origin; they carry the token instead.
    expect(validateWebSocketOrigin({ origin: undefined })).toBeUndefined()
  })
})

describe("pairing handshake", () => {
  const code = pairingCode(home)
  const relayNonce = ExtensionPairing.randomNonce()
  const extensionNonce = ExtensionPairing.randomNonce()
  const port = 19988

  test("the code is private and formatted for typing", () => {
    expect(code).toMatch(/^[0-9A-HJKMNP-TV-Z]{32}$/)
    expect(fs.statSync(path.join(home, "extension-pairing")).mode & 0o777).toBe(0o600)
    expect(ExtensionPairing.normalizePairingCode(formatPairingCode(code).toLowerCase())).toBe(code)
  })

  test("the extension accepts the relay's proof, and the relay the extension's", async () => {
    // Relay → extension: the relay proves it knows the code over both nonces.
    const relayProof = pairingProof(code, "relay", port, relayNonce, extensionNonce)
    expect(ExtensionPairing.sameSecret(await ExtensionPairing.pairingProof(code, "relay", port, relayNonce, extensionNonce), relayProof)).toBe(true)
    // Extension → relay.
    const extensionProof = await ExtensionPairing.pairingProof(code, "extension", port, extensionNonce, relayNonce)
    expect(secretsEqual(pairingProof(code, "extension", port, extensionNonce, relayNonce), extensionProof)).toBe(true)
  })

  test("a wrong code, swapped role or replayed nonce is refused", async () => {
    const other = pairingCode(fs.mkdtempSync(path.join(home, "other-")))
    expect(other).not.toBe(code)
    const relayProof = pairingProof(other, "relay", port, relayNonce, extensionNonce)
    expect(ExtensionPairing.sameSecret(await ExtensionPairing.pairingProof(code, "relay", port, relayNonce, extensionNonce), relayProof)).toBe(false)
    const extensionProof = await ExtensionPairing.pairingProof(other, "extension", port, extensionNonce, relayNonce)
    expect(secretsEqual(pairingProof(code, "extension", port, extensionNonce, relayNonce), extensionProof)).toBe(false)
    // A relay can't answer the extension with the extension's own proof (reflection) or an old nonce.
    expect(secretsEqual(pairingProof(code, "relay", port, relayNonce, extensionNonce), pairingProof(code, "extension", port, relayNonce, extensionNonce))).toBe(false)
    expect(secretsEqual(pairingProof(code, "relay", port, relayNonce, extensionNonce), pairingProof(code, "relay", port, relayNonce, ExtensionPairing.randomNonce()))).toBe(false)
  })

  test("a proof made for another relay port is refused", async () => {
    // A listener on another port that passes the handshake through to this relay: the extension proves for the port
    // it dialled, the relay checks against its own.
    const forwardedExtensionProof = await ExtensionPairing.pairingProof(code, "extension", 19989, extensionNonce, relayNonce)
    expect(secretsEqual(pairingProof(code, "extension", port, extensionNonce, relayNonce), forwardedExtensionProof)).toBe(false)
    const forwardedRelayProof = pairingProof(code, "relay", port, relayNonce, extensionNonce)
    expect(ExtensionPairing.sameSecret(await ExtensionPairing.pairingProof(code, "relay", 19989, relayNonce, extensionNonce), forwardedRelayProof)).toBe(false)
    expect(ExtensionPairing.pairingEndpoint(port)).toBe("127.0.0.1:19988/extension")
  })

  test("install writes the code into an unpacked extension folder", () => {
    const extension = fs.mkdtempSync(path.join(home, "extension-"))
    writeExtensionPairing(extension, code)
    const file = path.join(extension, "relay-pairing.json")
    expect(JSON.parse(fs.readFileSync(file, "utf8"))).toEqual({ code })
    expect(fs.statSync(file).mode & 0o777).toBe(0o600)
  })
})

import { expect, test } from "bun:test"
import type { AgentRelayState } from "../src/shared/protocol"
import { installChrome, settle, type StubEvent } from "./chrome-stub"

// The bundled pairing file (relay-pairing.json, written into an unpacked build by `install`) is looked for again
// while the extension is unpaired, and re-read on Reconnect and when the stored code changes. No relay: WebSocket is
// a fake that never opens unless told to. The fakes stay installed after this file: the relay it creates keeps its
// timers for the rest of the run, and must never reach a real port.

const stub = installChrome()
;(globalThis as { __OPENCODE_BROWSER_BUILD__?: string }).__OPENCODE_BROWSER_BUILD__ = "test"

class FakeWebSocket {
  static readonly CONNECTING = 0
  static readonly OPEN = 1
  static readonly CLOSING = 2
  static readonly CLOSED = 3
  static readonly made: FakeWebSocket[] = []
  readyState = FakeWebSocket.CONNECTING
  onopen: ((event: unknown) => void) | null = null
  onmessage: ((event: unknown) => void) | null = null
  onclose: ((event: unknown) => void) | null = null
  constructor(readonly url: string) {
    FakeWebSocket.made.push(this)
  }
  send() {}
  close(code = 1006, reason = "") {
    if (this.readyState === FakeWebSocket.CLOSED) return
    this.readyState = FakeWebSocket.CLOSED
    queueMicrotask(() => this.onclose?.({ code, reason, wasClean: false }))
  }
}

const CODE = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
const OTHER = "ZYXWVTSRQPNMKJHGFEDCBA9876543210"
let bundled: string | undefined
const reads: string[] = []
const realFetch = globalThis.fetch
globalThis.fetch = (async (input: string | URL) => {
  const url = String(input)
  if (!url.endsWith("/relay-pairing.json")) return realFetch(input)
  reads.push(url)
  return bundled === undefined ? new Response("not found", { status: 404 }) : Response.json({ code: bundled })
}) as typeof fetch
;(globalThis as { WebSocket: unknown }).WebSocket = FakeWebSocket

await stub.chrome.storage.local.set({ agentRelayPort: 19925 })
const { createAgentRelay } = await import("../src/background/agent-relay")
const states: AgentRelayState[] = []
const relay = createAgentRelay({ changed: (state) => states.push(state), badgesChanged: () => {} })
const until = async (check: () => boolean) => {
  for (let i = 0; i < 100 && !check(); i++) await settle()
  expect(check()).toBe(true)
}
const alarm = () => (chrome.alarms.onAlarm as unknown as StubEvent).emit({ name: "opencode-browser-relay" })

test("without a pairing file, the extension waits unpaired and doesn't connect", async () => {
  await until(() => relay.state().status === "unpaired")
  expect(relay.state().pairing).toBe("none")
  expect(FakeWebSocket.made).toHaveLength(0)
  expect(reads.length).toBeGreaterThan(0)
})

test("a pairing file written later (bun run setup) is found on the next attempt, without a worker restart", async () => {
  const before = reads.length
  bundled = CODE
  alarm()
  await until(() => FakeWebSocket.made.length === 1)
  expect(reads.length).toBe(before + 1)
  expect(relay.state().pairing).toBe("bundled")
  expect(FakeWebSocket.made[0]!.url).toBe("ws://127.0.0.1:19925/extension")
})

test("a found file is cached between attempts, and read again on Reconnect", async () => {
  // The relay isn't there: the attempt closes and backs off.
  FakeWebSocket.made[0]!.close()
  await settle()
  const before = reads.length
  alarm()
  await settle()
  // A retry is scheduled, so the alarm leaves it alone; either way nothing re-reads a found file.
  expect(reads.length).toBe(before)
  bundled = OTHER
  relay.reconnect()
  await until(() => FakeWebSocket.made.length === 2)
  expect(reads.length).toBe(before + 1)
})

test("a pairing change re-reads the file", async () => {
  const before = reads.length
  bundled = undefined
  await stub.chrome.storage.local.set({ agentRelayPairingCode: CODE })
  await until(() => reads.length === before + 1)
  // No file now; the stored code takes over.
  await until(() => relay.state().pairing === "stored")
})

import { beforeEach, describe, expect, test } from "bun:test"
